def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    colours = [c for c in np.unique(g) if c != bg]
    bars = []
    for c in colours:
        for comp in components(g == c):
            bars.append(comp)
    bars.sort(key=lambda cells: min(x for _, x in cells))
    for cells in bars:
        cells = sorted(cells)  # by row, top to bottom
        k = len(cells) // 2
        for (y, x) in cells[len(cells) - k:]:
            g[y, x] = 8
        if k > 0:
            emit(g, f"Bar at column {cells[0][1]} has height {len(cells)}: "
                    f"its bottom {k} cells (half, rounded down) become 8.")
    emit(g, "All bars processed: bottom half of every bar is 8.")
    return g
